import{_ as r,C as i,o as t,c as n,E as s,a2 as l}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"输出门禁需要持久化状态机，而不只是“晚一点保存”","description":"","frontmatter":{"title":"输出门禁需要持久化状态机，而不只是“晚一点保存”","date":"2026-08-05","column":"open-source-engineering","category":"daily","summary":"把最终消息推迟到门禁完成后再持久化是必要的，但被接受输出、保留的工具证据与可回放失败材料仍需要不同的持久状态。","item_id":"Q-20260805-14","source_research_object":"research/analysis/Q-20260805-14-guardrail-session-ordering.md","source_reading_result":"research/reading/Q-20260805-14-guardrail-session-ordering.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-05-guardrail-persistence-state-machine-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-05-guardrail-persistence-state-machine.md","filePath":"zh/engineering/2026-08-05-guardrail-persistence-state-machine.md","lastUpdated":1787407830000}'),o={name:"zh/engineering/2026-08-05-guardrail-persistence-state-machine.md"};function c(d,e,h,u,p,m){const a=i("ArticleCover");return t(),n("div",null,[s(a,{image:"/assets/covers/daily-2026-08-05-guardrail-persistence-state-machine-cover-v2.jpg",kicker:"开源工程 · 每日研究",title:"输出门禁需要持久化状态机，而不只是“晚一点保存”",summary:"把最终消息推迟到门禁完成后再持久化是必要的，但被接受输出、保留的工具证据与可回放失败材料仍需要不同的持久状态。",version:"Q-20260805-14",status:"Daily Runtime V5 · 2026-08-05",languageHref:"/en/engineering/2026-08-05-guardrail-persistence-state-machine",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="输出门禁需要持久化状态机-而不只是-晚一点保存" tabindex="-1">输出门禁需要持久化状态机，而不只是“晚一点保存” <a class="header-anchor" href="#输出门禁需要持久化状态机-而不只是-晚一点保存" aria-label="Permalink to &quot;输出门禁需要持久化状态机，而不只是“晚一点保存”&quot;">​</a></h1><p>把最终消息推迟到门禁完成后再持久化是必要的，但被接受输出、保留的工具证据与可回放失败材料仍需要不同的持久状态。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p>终结过程是有类型的状态机，不是一次保存操作。</p><h2 id="为什么这不是一个单点功能" tabindex="-1">为什么这不是一个单点功能 <a class="header-anchor" href="#为什么这不是一个单点功能" aria-label="Permalink to &quot;为什么这不是一个单点功能&quot;">​</a></h2><p>助手消息被阻断，并不代表整个回合已回滚：工具调用、工具输出和外部影响可能已经存在；错误与取消分支也可能为了可回放性保留未交付输出。单一且无类型的会话日志无法同时安全表达“已接受事实”和“取证证据”。</p><h2 id="可落地的最小架构" tabindex="-1">可落地的最小架构 <a class="header-anchor" href="#可落地的最小架构" aria-label="Permalink to &quot;可落地的最小架构&quot;">​</a></h2><p>明确 Provisional、GuardrailEvaluated、Accepted、BlockedWithRetainedEvidence、QuarantinedError、CancelledReplayable 与 Persisted 状态。将已接受输出与保留执行证据分开存储；每个重要外部影响都应拥有独立于消息持久化的幂等键和 effect receipt。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>现有测试使用假模型和简单列表会话，不能证明原子存储、回滚、外部影响恰好一次、并发写安全或分布式恢复正确性。</p><h2 id="工程结论" tabindex="-1">工程结论 <a class="header-anchor" href="#工程结论" aria-label="Permalink to &quot;工程结论&quot;">​</a></h2><p>在已接受输出投影之前引入明确的 FinalizationDecision，隔离可回放证据，并针对真实持久化适配器与外部影响系统测试崩溃边界。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图用于表达控制边界和状态关系，不表达实验结果，也不制造原始研究对象未支持的量化比较。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260805-14-guardrail-session-ordering.md" target="_blank" rel="noreferrer">Research Object</a>：本文唯一分析输入，包含研究判断、不确定性、反证和工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260805-14-guardrail-session-ordering.md" target="_blank" rel="noreferrer">Reading Result</a>：Research Object 的证据边界与来源追溯记录。</li></ol>',16))])}const b=r(o,[["render",c]]);export{_ as __pageData,b as default};
